/// Common generated framing boundary; implementation owns waiting and identity.
pub use abstraction_frame::FrameTransport;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ServiceError {
    pub code: String,
    pub message: String,
}

#[derive(Debug)]
pub enum CallError<E> {
    /// Transport failure does not establish whether the receiver accepted work.
    Transport(E),
    Refusal(Refusal),
    Dispatch(&'static str),
    Service(ServiceError),
}

fn service_decode<T>(data: &[u8], decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<T, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let value = decode(&mut r)?;
    r.skip_ws();
    if r.pos != data.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(value)
}

fn service_encode<T>(value: &T, check: fn(&T) -> Result<(), Refusal>, encode: fn(&mut Vec<u8>, &T, i32), decode: fn(&mut Reader) -> Result<T, Refusal>) -> Result<Vec<u8>, Refusal> {
    check(value)?;
    let mut data = Vec::new();
    encode(&mut data, value, 0);
    service_decode(&data, decode)?;
    Ok(data)
}

/// Common provider resolution vocabulary. Authorization comes from the
/// receiving boundary, never from request fields. See RESOLUTION.md for
/// selection and refusal semantics.
pub trait Resolver {
    type Error;
    /// Find an authorized ready candidate satisfying an exact acceptable
    /// contract and all required guarantees. Does not submit work, activate an
    /// embedded provider, or transfer ownership.
    fn resolve(&self, request: ResolveRequest) -> Result<ResolveResult, Self::Error>;
}

pub struct ResolverClient<T> {
    transport: T,
}

impl<T> ResolverClient<T> {
    pub fn new(transport: T) -> Self {
        Self { transport }
    }

    pub fn transport(&self) -> &T {
        &self.transport
    }
}

impl<T: FrameTransport> Resolver for ResolverClient<T> {
    type Error = CallError<T::Error>;
    fn resolve(&self, request: ResolveRequest) -> Result<ResolveResult, Self::Error> {
        let args = OAResolverResolveArguments { request };
        let arguments = service_encode(&args, service_check_oa_resolver_resolve_arguments, enc_oa_resolver_resolve_arguments, decode_oa_resolver_resolve_arguments).map_err(CallError::Refusal)?;
        let request = OAServiceFrame { version: 1, service: "abstraction.facade/resolver@1".into(), method: "Resolve".into(), arguments };
        let frame = service_encode(&request, service_check_oa_service_frame, enc_oa_service_frame, decode_oa_service_frame).map_err(CallError::Refusal)?;
        let reply = self.transport.exchange_frame(&frame).map_err(CallError::Transport)?;
        let reply = service_decode(&reply, decode_oa_service_reply).map_err(CallError::Refusal)?;
        if reply.version != 1 {
            return Err(CallError::Dispatch("unknown_version"));
        }
        if reply.service != "abstraction.facade/resolver@1" || reply.method != "Resolve" {
            return Err(CallError::Dispatch("mismatched_response"));
        }
        if !reply.ok {
            let error = service_decode(&reply.payload, decode_oa_service_error).map_err(CallError::Refusal)?;
            if error.code.is_empty() {
                return Err(CallError::Dispatch("invalid_error"));
            }
            return Err(CallError::Service(ServiceError { code: error.code, message: error.message }));
        }
        let result = service_decode(&reply.payload, decode_oa_resolver_resolve_result).map_err(CallError::Refusal)?;
        Ok(result.value)
    }
}

/// The runtime resolver endpoint's echo of its bound caller, for diagnostics
/// such as the control panel. Local transport only: a remote service states its
/// own authentication and never inherits these proofs.
pub trait Caller {
    type Error;
    /// Return what the receiving boundary bound for this connection's caller.
    /// It is the same Program evidence every runtime-hosted local service
    /// requires. unavailable means the binding could not be rechecked;
    /// forbidden is reserved for a boundary policy that withholds the echo;
    /// invalid for a request this provider cannot interpret. Observe grants,
    /// checks and changes nothing.
    fn observe(&self) -> Result<CallerObservation, Self::Error>;
}

