/// Experimental application-presence profile owned by the OA service.
/// Persistent operator descriptors and transient app announcements have
/// distinct authority and lifetime. This is a local directory; MCP/UI metadata
/// are claims, and invocation remains behind OA capability mediation. Native
/// callers retain their actual account/program identity. Unsupported platform
/// identity refuses access.
pub trait Applications {
    type Error;
    /// Add an installed descriptor. Requires application.manage on account;
    /// existing names conflict. Does not launch or grant use. Programs cannot
    /// self-register.
    fn register(&self, descriptor: ApplicationDescriptor) -> Result<ApplicationChange, Self::Error>;
    /// Remove an installed descriptor and its presence. Requires
    /// application.manage on account. Does not terminate user applications.
    fn remove(&self, application: String) -> Result<ApplicationChange, Self::Error>;
    /// Publish or renew presence. Requires application.announce on app:<name>,
    /// a bound native program and kernel session matching this runtime, and
    /// current owner/session/epoch for renewal. Claims never alter descriptors
    /// or grants.
    fn announce(&self, presence: ApplicationPresence) -> Result<ApplicationChange, Self::Error>;
    /// Withdraw only the bound program and session's own current instance.
    /// Requires application.announce on app:<name>. Does not terminate the
    /// application or remove its installed descriptor.
    fn withdraw(&self, application: String, instance: String) -> Result<ApplicationChange, Self::Error>;
    /// Read or wait for a caller-filtered complete snapshot. Requires
    /// application.read on each returned app:<name>; hidden entries and changes
    /// remain undisclosed. Empty cursor answers immediately. wait_ms is
    /// 0..30000; permissions and lease expiry are rechecked while waiting. No
    /// activation occurs.
    fn observe(&self, cursor: String, wait_ms: i64) -> Result<ApplicationPage, Self::Error>;
    /// Reuse a matching descriptor-program-bound presence or share one bounded
    /// authorized start attempt in this local runtime session. Requires
    /// application.activate on app:<name>. Only the operator-registered typed
    /// recipe executes; guidance and announcements remain inert. Caller
    /// cancellation stops its wait and never terminates or restarts the
    /// application.
    fn activate(&self, application: String) -> Result<ApplicationActivationResult, Self::Error>;
}

pub struct ApplicationsClient<T> {
    transport: T,
}

impl<T> ApplicationsClient<T> {
    pub fn new(transport: T) -> Self {
        Self { transport }
    }

    pub fn transport(&self) -> &T {
        &self.transport
    }
}

